SELECT ?z ?class ?label ?ts WHERE {
  ?z a ?class .
  FILTER(str(?class)="brick:Zone" || str(?class)="brick:Area" || str(?class)="brick:Room" || str(?class)="brick:Equipment")
  FILTER(CONTAINS(str(?z),"ZN_3") || CONTAINS(str(?z),"ZN_6"))
  OPTIONAL{ ?z rdfs:label ?label }
  OPTIONAL{ ?z ref:hasTimeseriesId ?ts }
}

SELECT ?z ?class ?label ?ts WHERE {
  ?z a ?class .
